import Foundation
import MapKit

/// Bundled route/station data and route geometry helpers used by the in-app map.
enum RouteGeometry {
    static let spanMiles = 70.0
    typealias Coord = CLLocationCoordinate2D

    // MARK: Bundled route + station data (generated by scripts/fetch_routes.py)

    static func slug(_ name: String) -> String {
        name.lowercased().split(whereSeparator: { !($0.isASCII && ($0.isLetter || $0.isNumber)) }).joined(separator: "-")
    }

    static func bundledURL(_ name: String) -> URL? {
        for b in [Bundle.main, Bundle(for: BundleToken.self)] {
            if let u = b.url(forResource: name, withExtension: "json") ?? b.url(forResource: name, withExtension: "json", subdirectory: "routes") { return u }
        }
        return nil
    }
    private final class BundleToken {}

    static func decodeCompact(_ data: Data) -> [[Coord]]? {
        guard let a = try? JSONSerialization.jsonObject(with: data) as? [[[Double]]] else { return nil }
        let out = a.map { $0.compactMap { $0.count >= 2 ? Coord(latitude: $0[0], longitude: $0[1]) : nil } }.filter { $0.count > 1 }
        return out.isEmpty ? nil : out
    }

    static func routePaths(routeName: String, stopCodes: [String]) -> [[Coord]] {
        if let u = bundledURL(slug(routeName)), let d = try? Data(contentsOf: u), let p = decodeCompact(d) { return p }
        // Fallback: station-to-station polyline from bundled coordinates.
        let all = allStations
        let pts = stopCodes.compactMap { all[$0] }
        return pts.count > 1 ? [pts] : []
    }

    static let allStations: [String: Coord] = {
        guard let u = bundledURL("stations"), let d = try? Data(contentsOf: u),
              let j = try? JSONSerialization.jsonObject(with: d) as? [String: [Double]] else { return [:] }
        return j.mapValues { Coord(latitude: $0[0], longitude: $0[1]) }
    }()

    static func stationCoord(code: String) -> Coord? { allStations[code] }

    // MARK: Geometry helpers

    static func headingDegrees(_ h: String?) -> Double? {
        let m = ["N": 0.0, "NE": 45, "E": 90, "SE": 135, "S": 180, "SW": 225, "W": 270, "NW": 315]
        return h.flatMap { m[$0.trimmingCharacters(in: .whitespaces).uppercased()] }
    }

    static func dist(_ a: Coord, _ b: Coord) -> Double { MKMapPoint(a).distance(to: MKMapPoint(b)) }

    static func bearing(_ a: Coord, _ b: Coord) -> Double {
        let dy = b.latitude - a.latitude
        let dx = (b.longitude - a.longitude) * cos(a.latitude * .pi / 180)
        return atan2(dx, dy) * 180 / .pi
    }

    /// Splits route geometry at the train into (traveled, remaining, other) polylines.
    static func split(paths: [[Coord]], train: Coord, heading: Double?) -> (traveled: [Coord], remaining: [Coord], other: [[Coord]]) {
        var best: (p: Int, v: Int, d: Double)?
        for (pi, path) in paths.enumerated() {
            for (vi, c) in path.enumerated() {
                let d = dist(c, train)
                if best == nil || d < best!.d { best = (pi, vi, d) }
            }
        }
        guard let b = best, let heading, b.d < 20_000 else { return ([], [], paths) }
        let path = paths[b.p]
        let a = path[max(0, b.v - 1)], c = path[min(path.count - 1, b.v + 1)]
        let forwardIsIncreasing = cos((bearing(a, c) - heading) * .pi / 180) >= 0
        var fwd = forwardIsIncreasing ? Array(path[b.v...]) : Array(path[...b.v].reversed())
        var back = forwardIsIncreasing ? Array(path[...b.v].reversed()) : Array(path[b.v...])
        var used: Set<Int> = [b.p]
        func extend(_ chain: inout [Coord]) {
            for _ in 0..<60 {
                guard let end = chain.last else { return }
                var cand: (i: Int, rev: Bool, d: Double)?
                for (i, p) in paths.enumerated() where !used.contains(i) && p.count > 1 {
                    let ds = dist(p.first!, end), de = dist(p.last!, end)
                    let (d, rev) = ds <= de ? (ds, false) : (de, true)
                    if d < 1500 && (cand == nil || d < cand!.d) { cand = (i, rev, d) }
                }
                guard let c = cand else { return }
                used.insert(c.i)
                chain += c.rev ? paths[c.i].reversed() : paths[c.i]
            }
        }
        extend(&fwd); extend(&back)
        let other = paths.enumerated().filter { !used.contains($0.offset) }.map { $0.element }
        return (Array(back.reversed()) + [train], [train] + fwd, other)
    }
}
